public class WindSlashBasic : MeleeAttackState
{
	public new static string staticID = "WindSlashBasic";

	private static string projSkillID = "WindSlashProjectile";

	private static Vector3 smallScale = new Vector3(0.5f, 0.5f, 1f);

	private static Vector3 medScale = new Vector3(0.625f, 0.625f, 1f);

	private static Vector3 largeScale = new Vector3(0.75f, 0.75f, 1f);

	public Projectile currentWS;

	public WindSlashBasic(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		isBasic = true;
		isMeleeSkill = true;
		attackPrefab = ChaosBundle.Get("Assets/Prefabs/PlayerSkills/WindSlashBasic.prefab");
		destroyAttackObjectOnExit = false;
		maxComboCount = 3;
		animStartTime = 0.15f;
		animExecTime = 0.3f;
		baseCancelThreshold = 0.5f;
		finalCancelThreshold = 0.5f;
		baseRunThreshold = 0.8f;
		finalRunThreshold = 0.9f;
		baseExitThreshold = 1f;
		finalExitThreshold = 1f;
		sfxNames = new string[maxComboCount];
		for (int i = 0; i < maxComboCount; i++)
		{
			sfxNames[i] = "WindSlashBasic";
		}
		autoHoldStat.BaseValue = true;
	}

	public override void ExecuteAttack()
	{
		base.ExecuteAttack();
		switch (calcComboCounter)
		{
		case 0:
			currentAttackObject.anim.Play("LargeSlashAlt", -1, 0f);
			if (IsEmpowered)
			{
				CreateEmpoweredProjectile(26f, largeScale);
			}
			break;
		case 1:
			currentAttackObject.anim.Play("MedSlashAlt", -1, 0f);
			if (IsEmpowered)
			{
				CreateEmpoweredProjectile(25f, medScale);
			}
			break;
		default:
			currentAttackObject.anim.Play("SmallSlashAlt", -1, 0f);
			if (IsEmpowered)
			{
				CreateEmpoweredProjectile(24f, smallScale);
			}
			break;
		}
	}

	private void CreateEmpoweredProjectile(float givenSpeed, Vector3 givenScale)
	{
		currentWS = Projectile.CreateProjectile(parent, WindSlashProjectile.Prefab, parent.attackOriginTrans.position, Globals.GetRotationQuaternion(inputVector), parent.transform.parent);
		currentWS.attackBox.SetAttackInfo(parent.skillCategory, projSkillID, currentLevel);
		currentWS.moveVector = inputVector;
		currentWS.moveSpeed = givenSpeed;
		currentWS.projectileCollisionModifier = 5f;
		currentWS.transform.localScale = givenScale;
	}
}

