		private int spawnCount;

		private Vector2 perpendVec;

		private WindArcherChargedArrow curArrow;

		private Vector2 calcPos;

		private float calcDelay;

		public AirChannelDash(FSM fsm, Player parentPlayer)
			: base(staticID, fsm, parentPlayer)
		{
			isProjectileSkill = true;
			InitChargeSkillSettings(1, 0f, skillData, this);
		}

		public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
		{
			base.SetEmpowered(givenStatus, givenMod);
			maxSpawnCount = ((!IsEmpowered) ? 3 : 5);
		}

		public override void OnEnter()
		{
			base.OnEnter();
			if (cooldownReady)
			{
				hitCompleted = false;
				hitStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, hitDelay, maxSpawnCount);
				spawnCount = 0;
				perpendVec = Globals.GetPerpendicular(inputVector);
			}
		}

		public override void FixedUpdate()
		{
			base.FixedUpdate();
			if (!hitCompleted)
			{
				switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
				{
				case StopwatchState.Ready:
					spawnCount++;
					SpawnArrow((Vector2)parent.attackOriginTrans.position + inputVector * 1.5f, spawnCount);
					break;
				case StopwatchState.Done:
					hitCompleted = true;
					break;
				}
			}
		}

		private void SpawnArrow(Vector2 givenPos, int index)
		{
			calcPos = Globals.GetSafeLinecastVector(givenPos, (index % 2 != 0) ? (-perpendVec) : perpendVec, UnityEngine.Random.Range(0.2f, 0.3f) * (float)(maxSpawnCount - index), ChaosCollisions.layerAllWallAndObst);
			calcDelay = (float)index * 0.1f + 0.05f;
			curArrow = WindArcherChargedArrow.Create(parent, calcPos, parent.skillCategory, skillID, 1, inputVector, 40f, 0.3f, 4, calcDelay);
			curArrow.wallCollider.offset = Vector2.zero;
			curArrow.transform.localScale = Globals.ScaleVec0p75;
			SectionedTrailEmitter poolItem = PoolManager.GetPoolItem<SectionedTrailEmitter>("WindTrail");
			Vector2 startPos = calcPos - inputVector * 2f;
			Vector2 endPos = calcPos + inputVector * 2f;
			float startLifetime = calcDelay + 0.25f;
			poolItem.Emit(startPos, endPos, -1, emitEveryOther: false, -1f, snapToFit: true, startLifetime);
		}
	}

