		PoolManager.GetPoolItem<ParticleEffect>("WindTwirlEffect").Emit(1, transform.position);
	}

	private void FixedUpdate()
	{
		if (atkCompleted)
		{
			return;
		}
		if (!atkStarted)
		{
			if (ChaosStopwatch.Check(atkStopwatchID))
			{
				atkStarted = true;
				atkStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, attackInterval, attackCount);
				frontPartSys.Play();
				frontPartSys2.Play();
				backPartSys.Play();
			}
			return;
