			SoundManager.PlayWithDistAndSPR("MetalSlash", transform.position);
			break;
		}
		case StopwatchState.Done:
		{
			atkCompleted = true;
			atkCollider.enabled = false;
			frontPartSys.Stop();
			frontPartSys2.Stop();
			backPartSys.Stop();
