			{
				particleSystem.Stop();
			}
			GetComponent<Animator>().Play("Hidden", -1, 0f);
			Object.Destroy(gameObject, 0.5f);
			PoolManager.GetPoolItem<ParticleEffect>("WindTwirlEffect").Emit(1, transform.position);
			break;
		}
		}
	}
