			return;
		}
		UpdateTargetVector();
		atkPosition = parent.attackOriginTrans.position;
		currentTF.transform.position = atkPosition + targetVector * holdRange;
		if (!isUltimate)
		{
			return;
		}
		ultLerpVal = ChaosStopwatch.GetTimePercentage(durationStopwatchID);
		calcHoldRange = Mathf.Lerp(ultHoldRange, holdRange, ultLerpVal);
		for (int i = 0; i < 4; i++)
		{
			if (ultFists[i] != null)
			{
				ultFists[i].transform.position = atkPosition + calcHoldRange * Vector2.Lerp(Globals.GetRotatedCircleVector(5, i + 1, targetVector), targetVector, ultLerpVal).normalized;
