public class Tornado : MonoBehaviour
{
	private static GameObject prefab;

	public int maxHitCount = 5;

	public bool specialLastHit = true;

	private int hitStopwatchID;

	public float hitDelay = 0.125f;

	private bool hitCompleted;

	public Rigidbody2D rigidbody2D;

	public Animator anim;

	public Attack attackBox;

	[HideInInspector]
	public bool useCamShake = true;

	private bool isUltimate;

	private AudioSource tornadoAudio;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/Tornado.prefab"));

	public bool AttackComplete => hitCompleted;

	private void Start()
	{
		isUltimate = attackBox.atkInfo.isUltimate;
		attackBox.ChangeAttackInfoLevel((!isUltimate) ? 1 : 3);
		SoundManager.PlayAudioWithDistance("TornadoStart", transform.position);
		hitStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, hitDelay, maxHitCount);
		if (useCamShake)
		{
			CameraController.ShakeCamera(0.5f);
		}
		if (maxHitCount <= 2)
		{
			anim.Play("Spin", -1, 0f);
		}
	}

	private void FixedUpdate()
	{
		if (hitCompleted)
		{
			return;
		}
		switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
		{
		case StopwatchState.Running:
			attackBox.collider.enabled = false;
			PlayAudio(status: true);
			break;
		case StopwatchState.Ready:
			if (specialLastHit && !ChaosStopwatch.IntervalIsActive(hitStopwatchID))
			{
				if (useCamShake)
				{
					CameraController.ShakeCamera(0.25f);
				}
				attackBox.ChangeAttackInfoLevel((!isUltimate) ? 2 : 4);
			}
			attackBox.collider.enabled = true;
			break;
		case StopwatchState.Done:
		{
			attackBox.collider.enabled = false;
			PlayAudio(status: false);
			anim.Play("Dissipate");
			hitCompleted = true;
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 150;
			float scale = 1.5f;
			Vector3? emitPosition = transform.position + Vector3.down;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
			SoundManager.PlayAudioWithDistance("TornadoEnd", transform.position);
			break;
		}
		}
	}

	private void PlayAudio(bool status)
	{
		if (status)
		{
			if (tornadoAudio == null || !tornadoAudio.isPlaying)
			{
				tornadoAudio = SoundManager.PlayAudioWithDistance("TornadoLoop", transform.position);
			}
		}
		else if (tornadoAudio != null)
		{
			tornadoAudio.Stop();
			tornadoAudio = null;
		}
	}

	public void RefreshTornado(int givenCount = 5)
	{
		hitCompleted = false;
		hitStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, hitDelay, givenCount);
	}

	public void StopTornado()
	{
		ChaosStopwatch.Stop(hitStopwatchID);
	}
}
