		SetAnimTimes(0.2f, 0.2f, 0.3f, 0.55f, 0.75f);
	}

	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		currentCA = (CupidArrow)CreateProjectile(CupidArrow.Prefab, parent.attackOriginTrans.position, Globals.GetRotationQuaternion(inputVector));
		Attack attackBox = currentCA.attackBox;
		attackBox.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attackBox.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		Attack attackBox2 = currentCA.attackBox;
		attackBox2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attackBox2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		FireProjectile(currentCA, inputVector, setKnockbackVector: true, 0f, 0f, string.Empty);
	}

	private void OnTargetHit(Entity givenEnt)
	{
		if (!(givenEnt == null))
		{
			SetBuffStatus(currentTarget, givenStatus: false);
			SetBuffStatus(givenEnt, givenStatus: true);
			currentTarget = givenEnt;
			if (currentCA != null)
			{
				Attack attackBox = currentCA.attackBox;
				attackBox.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attackBox.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			}
		}
	}

	private void SetBuffStatus(Entity givenEnt, bool givenStatus)
	{
		if (TargetIsValid(givenEnt))
		{
			if (givenStatus)
			{
				SoundManager.PlayAudioWithDistance("Charm", givenEnt.transform.position);
				givenEnt.dotManager.AddDot(new MindControlCloudDotEffect(givenEnt, 300f, IsEmpowered));
