	}

	private bool TargetIsValid(Entity givenEnt)
	{
		return !(givenEnt == null) && givenEnt is Enemy && !(givenEnt is MiniBoss) && !(givenEnt is Boss) && givenEnt.dotManager != null && !givenEnt.health.ignoreGrab;
	}
