		firstFrame = true;
		fallAnimPlayed = false;
		Animator animator = ChaosInst<Animator>(TornadoKick.WindPillarPrefab, startPosition);
		animator.speed = 0.7f;
		animator.Play("Swirl", -1, 0.33f);
		calcPitch = 0.75f;
	}

	public override void Update()
	{
		if (!hasLanded)
		{
			if (!fallAnimPlayed && !parentThrow.isFalling && !audioStopwatch.IsRunning)
			{
				audioStopwatch.IsRunning = true;
				string audioID = "WindCircle";
				Vector2? soundOrigin = parent.transform.position;
				float overridePitch = calcPitch;
				SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.5f, overridePitch, ignoreTimeRestriction: true);
				calcPitch += 0.05f;
			}
			if (fallAnimPlayed || !parentThrow.isFalling)
			{
				return;
			}
			fallAnimPlayed = true;
			parent.anim.PlayDirectional(parent.FallAnimStr, -1, 1f);
			SetThrowVars(0.1f, jumpHeight, 0f);
			if (isUltimate)
			{
				parentThrow.ThrowToTargetVector((ultCounter % 2 != 0) ? ultStartPos : ultEndPos);
				if (ultInProgress)
				{
					inputVector = -inputVector;
				}
			}
			else
			{
				parentThrow.ThrowToTargetVector(Globals.GetSafeLinecastVector(startPosition, inputVector, 6f, ChaosCollisions.layerAllWallAndObst));
			}
			Vector3 vector = parent.spriteRenderer.transform.position + Vector3.up;
			Vector3 normalized = (vector - (Vector3)parentThrow.targetPosition).normalized;
			PoolManager.GetPoolItem<SectionedTrailEmitter>("WindTrail").Emit(vector, parentThrow.targetPosition + Vector2.up, -1, emitEveryOther: false, -1f, snapToFit: true, -1f, 0.1f);
			PoolManager.GetPoolItem<SectionedTrailEmitter>("WindTrail").Emit(vector, parentThrow.targetPosition + Vector2.up, -1, emitEveryOther: false, -1f, snapToFit: true, -1f, 0.2f);
			PoolManager.GetPoolItem<DashAirBurst>().Burst(vector, normalized, useOffset: false);
			return;
		}
		if (atkQueued)
		{
			if (firstFrame)
			{
				firstFrame = false;
				parent.anim.PlayDirectional(parent.GSlamAnimStr, -1, animExecTime);
				return;
			}
			atkQueued = false;
			if (IsEmpowered)
			{
				empCompleted = ultInProgress;
				empCounter = 0;
				calcDelay = 0.1f;
				empStopwatchID = ChaosStopwatch.Begin(calcDelay);
			}
			CameraController.ShakeCamera();
			CreateWindSlam(parent.attackOriginTrans.position, (!isUltimate || !ultInProgress) ? 1 : 3);
			SoundManager.PlayWithDistAndSPR("ThrowBoulder", startPosition);
			return;
		}
		if (landingStopwatch.IsRunning && parent.anim.AnimPlayed(cancelThreshold))
		{
			parent.anim.PlayDirectional(parent.GSlamAnimStr, -1, cancelThreshold);
		}
		if (CancelToSkills())
		{
			return;
		}
		if (!empCompleted)
		{
			if (!ChaosStopwatch.Check(empStopwatchID))
			{
				return;
			}
			if (empCounter < 2)
			{
				empCounter++;
				CreateWindSlam(parent.attackOriginTrans.position + (Vector3)inputVector * 1.5f * empCounter, 2);
				calcDelay *= 0.75f;
				empStopwatchID = ChaosStopwatch.Begin(calcDelay);
				return;
			}
			empCompleted = true;
		}
		if (isUltimate && ultCounter < ultJumpCount)
		{
			ultCounter++;
			ultInProgress = ultCounter < ultJumpCount;
			if (!ultInProgress)
			{
				SetCameraLock(givenStatus: false);
				jumpTime = 0.5f;
				landingDelay = 0.25f;
			}
			parent.FaceTarget((Vector2)parent.transform.position + inputVector);
			SetOnEnterVars();
		}
		else
		{
			base.Update();
		}
	}

	public override void OnExit()
	{
		if (isUltimate)
		{
			SetCameraLock(givenStatus: false);
		}
		base.OnExit();
		ultCounter = 0;
	}

	public override void OnLanding()
	{
		base.OnLanding();
		atkQueued = true;
		if (!ultInProgress)
		{
			parent.airborneStat.RemoveMod(airborneStatMod);
			parent.TogglePreventFallCollider(status: true);
		}
	}

	private void SetThrowVars(float givenTime, float givenHeight, float givenBalance)
	{
		parentThrow.baseFlightTime = givenTime;
		parentThrow.throwHeight = givenHeight;
		parentThrow.isFallingThreshold = givenBalance;
	}

	private void CreateWindSlam(Vector2 givenPosition, int givenLevel = 1)
	{
		currentWS = ChaosInst<WindSlam>(WindSlam.Prefab, givenPosition, Globals.GetRotationQuaternion(inputVector));
		currentWS.attack.SetAttackInfo(parent.skillCategory, skillID, givenLevel, isUltimate);
		currentWS.attack.knockbackOverwriteVector = inputVector;
		if (inputVector.x < 0f)
		{
			currentWS.transform.localScale = new Vector3(-1f, 1f, 1f);
		}
	}

	private void SetCameraLock(bool givenStatus)
	{
		if (givenStatus)
		{
			camStartPos = parent.cameraLockTransform.localPosition;
			parent.cameraLockTransform.SetParent(null);
		}
		else
		{
			parent.cameraLockTransform.SetParent(parent.transform);
			parent.cameraLockTransform.localPosition = camStartPos;
		}
	}
}

public class BaseJumpState : SkillState
{
	protected ThrownItem parentThrow;

	protected Vector2 startPosition;

	protected bool useCalcValues;

	protected float jumpRange = 5.5f;

	protected float jumpSpeed = 32f;

	protected float jumpTime = 0.5f;

	protected float jumpHeight = 1f;

	protected float jumpBalance = 0.5f;

	protected bool hasLanded;

	protected bool collidersEnabled;

	protected float landingDelay;

	protected ChaosQuickStopwatch landingStopwatch = new ChaosQuickStopwatch();

	public bool setInputVectorOnEnter = true;

	protected BoolVarStatMod airborneStatMod;

	public BaseJumpState(string skillID, FSM fsm, Player player)
		: base(skillID, fsm, player)
	{
		isMovementSkill = true;
		isJumpSkill = true;
		parentThrow = parent.throwScript;
		airborneStatMod = new BoolVarStatMod(skillID, newModValue: true, 3);
	}

	public override void OnEnter()
	{
		BaseOnEnter();
		base.ExecuteSkill();
		if (setInputVectorOnEnter)
		{
			inputVector = GetInputVector();
		}
		startPosition = parent.transform.position;
		parent.spriteRenderer.sortingLayerName = "UI";
		SetThrowValues();
		parentThrow.ThrowToTargetVector(Globals.GetSafeLinecastVector(startPosition, inputVector, jumpRange, ChaosCollisions.layerAllWallAndObst));
		landingStopwatch.SetDelay(landingDelay);
		SoundManager.PlayAudioWithDistance("StandardJump", startPosition);
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 50;
		float scale = 0.25f;
		Vector3? emitPosition = startPosition;
		poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
		hasLanded = false;
		collidersEnabled = false;
		ThrownItem thrownItem = parentThrow;
		thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
		ThrownItem thrownItem2 = parentThrow;
		thrownItem2.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Combine(thrownItem2.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
		ToggleObjects(status: false);
	}

	public override void Update()
	{
		if (hasLanded)
		{
			if (!collidersEnabled)
			{
				collidersEnabled = true;
				ToggleObjects(status: true);
			}
			if (!landingStopwatch.IsRunning)
			{
				ExitToSkillOrRunOrIdle();
			}
		}
	}

	public override void OnExit()
	{
		if (!hasLanded)
		{
			OnLanding();
		}
		base.OnExit();
		ToggleObjects(status: true);
		ThrownItem thrownItem = parentThrow;
		thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
	}

	public virtual void OnLanding()
	{
		hasLanded = true;
		landingStopwatch.IsRunning = true;
		parent.spriteRenderer.sortingLayerName = "Actor";
	}

	public virtual void ToggleObjects(bool status)
	{
		parent.airborneStat.Modify(airborneStatMod, !status);
		if (parent.hurtBoxObj != null && parent.hurtBoxObj.activeSelf != status)
		{
			parent.hurtBoxObj.SetActive(status);
		}
		if (parent.floorContact != null && parent.floorContact.activeSelf != status)
		{
			parent.floorContact.SetActive(status);
		}
		parent.TogglePreventFallCollider(status);
	}

	public virtual void SetThrowValues()
	{
		parentThrow.useCalculatedValues = useCalcValues;
		parentThrow.moveSpeed = jumpSpeed;
		parentThrow.baseFlightTime = jumpTime;
		parentThrow.throwHeight = jumpHeight;
		parentThrow.isFallingThreshold = jumpBalance;
	}
}

public class UseHeroicLeap : SkillState
{
	public new static string staticID = "UseHeroicLeap";

	private bool finishedDashing;

	private NumVarStatMod dashDurMod;

	private GameObject currentAtkObj;

	private Attack currentAtk;

	private Entity targetEntity;

	private bool targetHit;

	private bool targetGrabbed;

	private bool targetReleased;

	private ThrownItem parentThrow;

	private bool hasJumped;

	private bool hasLanded;

	private Vector2 preDashPos;

	private BoolVarStatMod airborneStatMod;

	private Transform spriteTrans;

	private Tornado currentTO;

	private bool fallJumpStarted;

	public UseHeroicLeap(FSM parentFSM, Player parentEnt)
		: base(staticID, parentFSM, parentEnt)
	{
		isMovementSkill = true;
		isJumpSkill = true;
		isMeleeSkill = true;
		applyStopElementStatus = true;
		SetAnimTimes(0f, 0.2f, 0.3f, 0.7f, 1f);
		parentThrow = parent.throwScript;
		dashDurMod = new NumVarStatMod(staticID, 0.125f, 10, VarStatModType.OverrideWithMods);
		airborneStatMod = new BoolVarStatMod(staticID, newModValue: true, 3);
	}

	public override void OnEnter()
	{
		BaseOnEnter();
		base.ExecuteSkill();
		parent.movement.EndMovement();
		inputVector = GetInputVector();
		preDashPos = parent.attackOriginTrans.position;
		parent.movement.dashDurationStat.AddMod(dashDurMod);
		parent.movement.dashTimer = dashDurMod.modValue;
		parent.movement.dashVector = inputVector;
		parent.anim.PlayDirectional(parent.SlideAnimStr, -1, animStartTime);
		SoundManager.PlayAudioWithDistance("VacuumShot", parent.transform.position, null, 24f, -1f, 0.85f);
		PoolManager.GetPoolItem<DashAirBurst>().Burst(parent.attackOriginTrans.position, inputVector);
		parent.TogglePreventFallCollider(status: false);
		parent.ToggleEnemyFloorCollisions(status: false);
		CreateDashAttack();
		spriteTrans = parent.spriteRenderer.transform;
		finishedDashing = false;
		targetHit = false;
		targetGrabbed = false;
		targetReleased = false;
		hasJumped = false;
		hasLanded = false;
		fallJumpStarted = false;
	}

	public override void Update()
	{
		if (!finishedDashing)
		{
			return;
		}
		if (!hasJumped)
		{
			hasJumped = true;
			InitJump();
		}
		else if (!hasLanded)
		{
			if (parentThrow.isFalling)
			{
				if (targetGrabbed)
				{
					parent.anim.PlayDirectional(parent.GSlamAnimStr, -1, animStartTime);
				}
				else
				{
					parent.anim.PlayDirectional(parent.FallAnimStr, -1, 1f);
				}
				if (!fallJumpStarted)
				{
					fallJumpStarted = true;
					parentThrow.baseFlightTime = 0.125f;
					parentThrow.isFallingThreshold = 0f;
					parentThrow.ThrowToTargetVector((Vector2)parent.transform.position + inputVector * 0.25f);
				}
			}
		}
		else if (!targetReleased)
		{
			targetReleased = true;
			FinalHitEnemy();
			parent.anim.PlayDirectional(parent.GSlamAnimStr, -1, 0.5f);
		}
		else
		{
			ExitToSkillOrRunOrIdle();
		}
	}

	public override void FixedUpdate()
	{
		if (!finishedDashing)
		{
			if (parent.movement.DashToTarget())
			{
				finishedDashing = true;
				PoolManager.GetPoolItem<SectionedTrailEmitter>("WindTrail").Emit(preDashPos - inputVector, parent.attackOriginTrans.position, 2);
			}
			if (currentAtk != null)
			{
				currentAtk.rigidbody2D.MovePosition((Vector2)parent.attackOriginTrans.position + inputVector);
			}
		}
		if (!hasLanded)
		{
			MoveTargetEntity((Vector2)spriteTrans.position + inputVector * 0.75f);
		}
	}

	public override void OnExit()
	{
		if (hasJumped && !hasLanded)
		{
			OnLanding();
			if (targetHit && !targetReleased && targetEntity != null)
			{
				targetEntity.transform.position = parent.transform.position;
				MoveTargetEntity(parent.transform.position);
			}
		}
		base.OnExit();
		ToggleObjects(status: true);
		parent.ToggleEnemyFloorCollisions();
		parent.movement.dashDurationStat.RemoveMod(dashDurMod);
		CleanUpObjects();
		ThrownItem thrownItem = parentThrow;
		thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
	}

	private void SetHitTarget(Entity givenEnt)
	{
		if (!targetHit && !hasJumped && !(givenEnt == null) && !(givenEnt is Destructible))
		{
			targetEntity = givenEnt;
			targetEntity.ignorePrevHitStunDuration = true;
			targetHit = true;
			finishedDashing = true;
			parent.movement.EndMovement();
			targetGrabbed = targetEntity.health != null && !targetEntity.health.ignoreGrab && targetEntity.health.shieldStat.CurrentValue <= 0f;
			if (targetGrabbed)
			{
				currentAtk.atkInfo.showDamageEffect = true;
			}
			else
			{
				targetEntity = null;
			}
			currentAtkObj.SetActive(value: false);
		}
	}

	private void InitJump()
	{
		CameraController.ShakeCamera(0.25f);
		parent.anim.PlayDirectional(parent.JumpAnimStr, -1, animStartTime);
		SoundManager.PlayAudioWithDistance("ThrowBoulder", parent.transform.position);
		parentThrow.useCalculatedValues = false;
		parentThrow.moveSpeed = 1f;
		parentThrow.baseFlightTime = 0.625f;
		parentThrow.throwHeight = 5f;
		parentThrow.isFallingThreshold = 0.8f;
		parentThrow.useLineCastPosition = true;
		parentThrow.ThrowToTargetVector((Vector2)parent.transform.position + inputVector * 0.5f);
		ThrownItem thrownItem = parentThrow;
		thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Combine(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
		ToggleObjects(status: false);
		CreateTornado((!targetGrabbed) ? null : targetEntity.hurtBoxTransform.gameObject);
	}

	private void CreateDashAttack()
	{
		GameObject circlePrefab = Attack.CirclePrefab;
		Transform attackOriginTrans = parent.attackOriginTrans;
		currentAtk = ChaosInst<Attack>(circlePrefab, null, null, attackOriginTrans);
		currentAtk.SetAttackInfo(parent.skillCategory, skillID, 3);
		Attack attack = currentAtk;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(SetHitTarget));
		Attack attack2 = currentAtk;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(SetHitTarget));
		currentAtk.knockbackOverwriteVector = inputVector;
		currentAtkObj = currentAtk.gameObject;
		if (IsEmpowered)
		{
			currentAtkObj.transform.localScale *= 1.5f;
		}
	}

	public void OnLanding()
	{
		hasLanded = true;
		ToggleObjects(status: true);
		CameraController.ShakeCamera(0.5f);
	}

	private void FinalHitEnemy()
	{
		parent.anim.PlayDirectional(parent.GSlamAnimStr, -1, animExecTime);
		if (targetGrabbed && targetEntity != null)
		{
			targetEntity.transform.position = parent.transform.position;
			currentAtk.ChangeAttackInfoLevel(5);
			targetEntity.ignorePrevHitStunDuration = true;
			if (Vector2.Distance(targetEntity.transform.position, parent.transform.position) < 4f)
			{
				targetEntity.health.TakeDamage(currentAtk.atkInfo, parent);
			}
			CreateTornado(targetEntity.gameObject, isFinal: true);
		}
		else
		{
			CreateTornado(null, isFinal: true);
		}
	}

	public void ToggleObjects(bool status)
	{
		parent.airborneStat.Modify(airborneStatMod, !status);
		parent.TogglePreventFallCollider(status);
		parent.spriteRenderer.sortingLayerName = ((!status) ? "UI" : "Actor");
		parent.hurtBoxObj.SetActive(status);
		parent.floorContact.SetActive(status);
		if (targetGrabbed && targetEntity != null)
		{
			targetEntity.airborneStat.Modify(airborneStatMod, !status);
			targetEntity.TogglePreventFallCollider(status);
			if (targetEntity.spriteRenderer != null)
			{
				targetEntity.spriteRenderer.sortingLayerName = ((!status) ? "UI" : "Actor");
			}
			if (targetEntity.shadowSprite != null)
			{
				targetEntity.shadowSprite.gameObject.SetActive(status);
			}
			if (targetEntity.hurtBoxTransform != null)
			{
				targetEntity.hurtBoxTransform.gameObject.SetActive(status);
			}
			if (targetEntity.floorContact != null)
			{
				targetEntity.floorContact.SetActive(status);
			}
		}
	}

	private void CreateTornado(GameObject ignoreObj = null, bool isFinal = false)
	{
		currentTO = ChaosInst<Tornado>(Tornado.Prefab, parent.attackOriginTrans.position);
		currentTO.attackBox.knockbackOverwriteVector = inputVector;
		currentTO.attackBox.SetAttackInfo(parent.skillCategory, skillID, 1, isFinal && IsEmpowered);
		currentTO.specialLastHit = isFinal;
		currentTO.hitDelay = 0.125f;
		currentTO.maxHitCount = (isFinal ? 1 : 5);
		if (ignoreObj != null)
		{
			currentTO.attackBox.ignoreTargetsList.Add(ignoreObj.GetInstanceID());
		}
		if (!isFinal)
		{
			ChaosInst<Animator>(TornadoKick.WindPillarPrefab, parent.attackOriginTrans.position).speed = 1.5f;
		}
	}

	private void CleanUpObjects()
	{
		Attack attack = currentAtk;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(SetHitTarget));
		if (currentAtkObj != null)
		{
			UnityEngine.Object.Destroy(currentAtkObj);
		}
	}

	private void MoveTargetEntity(Vector2 givenPosition)
	{
		if (targetGrabbed && !(targetEntity == null) && !targetEntity.health.IgnoreKnockback)
		{
			targetEntity.rigidbody2D.MovePosition(givenPosition);
		}
	}
