public class UseWhirlwind : SkillState
{
	public new static string staticID = "UseWhirlwind";

	private static ParticleSystemOverride _vortexOverride;

	private static ParticleSystemOverride _vortexOverrideBG;

	private static ParticleSystemOverride _vortexOverrideBGWorld;

	private float duration = 1f;

	private int maxHitCount = 8;

	private float hitDelay = 1f;

	private int hitStopwatchID = -1;

	private bool intervalThresholdHit;

	private float intervalThreshold = 0.25f;

	private NumVarStatMod moveSpeedMod;

	private bool movementDone;

	private bool onExitCalled;

	private GameObject currentAtkObj;

	private Attack currentAtk;

	private ParticleEffect vortexEffect0;

	private ParticleEffect vortexEffect1;

	private ParticleEffect vortexEffect2;

	private ParticleEffect twirlEffect0;

	private ParticleEffect twirlEffect1;

	private AudioSource spinAudio;

	private AirBossVortex curVortex;

	private Tornado curTornado;

	private ChaosQuickStopwatch ultStopwatch;

	private bool ultStarted;

	public static ParticleSystemOverride VortexOverride
	{
		get
		{
			if (_vortexOverride == null)
			{
				ParticleSystemOverride particleSystemOverride = new ParticleSystemOverride();
				particleSystemOverride.sortingLayer = "Trail";
				particleSystemOverride.startLifetime = 0.66f;
				particleSystemOverride.startColor = new Color(1f, 1f, 1f, 0.75f);
				_vortexOverride = particleSystemOverride;
			}
			return _vortexOverride;
		}
	}

	public static ParticleSystemOverride VortexOverrideBG
	{
		get
		{
			if (_vortexOverrideBG == null)
			{
				ParticleSystemOverride particleSystemOverride = new ParticleSystemOverride();
				particleSystemOverride.sortingLayer = "Trail";
				particleSystemOverride.startLifetime = 0.75f;
				particleSystemOverride.startColor = new Color(1f, 1f, 1f, 0.25f);
				_vortexOverrideBG = particleSystemOverride;
			}
			return _vortexOverrideBG;
		}
	}

	public static ParticleSystemOverride VortexOverrideBGWorld
	{
		get
		{
			if (_vortexOverrideBGWorld == null)
			{
				ParticleSystemOverride particleSystemOverride = new ParticleSystemOverride();
				particleSystemOverride.sortingLayer = "Trail";
				particleSystemOverride.startLifetime = 0.75f;
				particleSystemOverride.startColor = new Color(1f, 1f, 1f, 0.15f);
				particleSystemOverride.simulationSpace = ParticleSystemSimulationSpace.World;
				_vortexOverrideBGWorld = particleSystemOverride;
			}
			return _vortexOverrideBGWorld;
		}
	}

	public UseWhirlwind(FSM parentFSM, Player parentEnt)
		: base(staticID, parentFSM, parentEnt)
	{
		hasSignatureVariant = true;
		isMovementSkill = true;
		isMeleeSkill = true;
		applyStopElementStatus = true;
		SetAnimTimes(0.15f, 0.2f, 0.3f, 0.5f);
		moveSpeedMod = new NumVarStatMod(skillID, 12f, 10, VarStatModType.Override);
		ultStopwatch = new ChaosQuickStopwatch(0.15f);
	}

	public override void OnEnter()
	{
		InitSkillSettings();
		BaseOnEnter();
		base.ExecuteSkill();
		onExitCalled = false;
		intervalThresholdHit = false;
		hitDelay = duration / (float)maxHitCount;
		if (!isUltimate)
		{
			hitStopwatchID = ChaosStopwatch.Begin(hitDelay, useInterval: true, hitDelay, maxHitCount);
		}
		movementDone = false;
		inputVector = GetInputVector(faceInputVector: true, useAimVector: false);
		parent.movement.dashVector = inputVector;
		PlaySpinAnim();
		if (isUltimate)
		{
			PoolManager.GetPoolItem<AttackGeneric>().CircleAttack(parent.transform.position, parent.skillCategory, skillID, 3, isUltimate, 6f);
			ultStarted = false;
			ultStopwatch.IsRunning = true;
			parent.anim.PlayDirectional(parent.PBAoEAnimStr, -1, 0.25f);
			curVortex = ChaosInst<AirBossVortex>(AirBossVortex.Prefab, parent.transform.position);
			curVortex.useAttackBox = false;
			curVortex.useGravityEffector = false;
			curVortex.followTrans.followTransform = parent.transform;
			curVortex.useParticleEffects = false;
			curVortex.dustShapeMod.radius = 6.25f;
			curVortex.debrisShapeMod.radius = 5.25f;
			curVortex.lightStreakShapeMod.radius = 5.25f;
			curVortex.dustEmitter.Emit(140);
			curVortex.debrisEmitter.Emit(80);
			curVortex.lightStreakEmitter.Emit(12);
			curTornado = ChaosInst<Tornado>(Tornado.Prefab, parent.transform.position);
			curTornado.maxHitCount = 20;
			curTornado.transform.SetParent(curVortex.transform);
			curTornado.transform.localPosition = new Vector3(0f, 0.25f, 0f);
		}
		else
		{
			vortexEffect0 = PoolManager.GetPoolItem<ParticleEffect>("AirVortex");
			vortexEffect0.reqFollowTrans = true;
			ParticleEffect particleEffect = vortexEffect0;
			float? emissionRate = 24f;
			Vector3? position = parent.attackOriginTrans.position;
			Transform attackOriginTrans = parent.attackOriginTrans;
			ParticleSystemOverride vortexOverrideBG = VortexOverrideBG;
			particleEffect.Play(emissionRate, position, vortexOverrideBG, null, attackOriginTrans);
			twirlEffect0 = PoolManager.GetPoolItem<ParticleEffect>("WindTwirlEffect");
			twirlEffect0.reqFollowTrans = true;
			twirlEffect0.Play(2f, parent.attackOriginTrans.position, followTransform: parent.attackOriginTrans, localEulerAngles: new Vector3(0f, 0f, 25f), overrides: ParticleEffectOverrides.StartLifeTime0p25);
		}
		parent.ToggleEnemyFloorCollisions(status: false);
		parent.movement.moveVector = inputVector;
		parent.movement.moveSpeedStat.AddMod(moveSpeedMod);
		currentAtkObj = UnityEngine.Object.Instantiate(Attack.CirclePrefab, parent.transform.position, Quaternion.identity, parent.attackOriginTrans);
		currentAtk = currentAtkObj.GetComponent<Attack>();
		currentAtk.SetAttackInfo(parent.skillCategory, skillID, (!IsEmpowered) ? 1 : 2, isUltimate);
		((CircleCollider2D)currentAtk.collider).radius = 3f;
		parent.StartCoroutine(PlayDelayedAirVortex());
		CameraController.ShakeCamera(0.3f);
		SetAudioStatus(givenStatus: true);
	}

	public override void Update()
	{
		inputVector = GetInputVector(faceInputVector: true, useAimVector: false);
		parent.FaceTarget(parent.transform.position + (Vector3)inputVector);
		if ((!intervalThresholdHit || !CancelToSkills(overrideThresholdReq: true)) && movementDone)
		{
			parent.movement.dashVector = inputVector;
			fsm.ChangeState(SlideState.staticID);
		}
	}

	public override void FixedUpdate()
	{
		if (isUltimate && !ultStarted)
		{
			if (ultStopwatch.IsRunning)
			{
				return;
			}
			ultStarted = true;
			PlaySpinAnim();
			hitStopwatchID = ChaosStopwatch.Begin(hitDelay, useInterval: true, hitDelay, maxHitCount);
		}
		if (!movementDone)
		{
			currentAtk.transform.position = parent.attackOriginTrans.position;
			parent.movement.moveVector = inputVector;
			parent.movement.MoveToMoveVector();
			switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
			{
			case StopwatchState.Running:
				currentAtk.collider.enabled = true;
				break;
			case StopwatchState.Ready:
			{
				intervalThresholdHit = (float)ChaosStopwatch.GetRemainingIntervals(hitStopwatchID) / (float)maxHitCount <= intervalThreshold;
				currentAtk.collider.enabled = false;
				DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
				int particleCount = 80;
				float scale = 0.25f;
				Vector3? emitPosition = parent.transform.position;
				poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
				break;
			}
			case StopwatchState.Done:
				movementDone = true;
				SetAudioStatus(givenStatus: false);
				break;
			}
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		onExitCalled = true;
		parent.ToggleEnemyFloorCollisions();
		CleanUpObjects();
		SetAudioStatus(givenStatus: false);
	}

	private void InitSkillSettings()
	{
		if (isUltimate)
		{
			duration = 2f;
			maxHitCount = 20;
			moveSpeedMod.modValue = 15f;
		}
		else if (IsEmpowered)
		{
			duration = 1.25f;
			maxHitCount = 10;
			moveSpeedMod.modValue = 15f;
		}
		else
		{
			duration = 1f;
			maxHitCount = 8;
			moveSpeedMod.modValue = 12f;
		}
	}

	private void PlaySpinAnim()
	{
		if (inputVector.x < 0f)
		{
			parent.anim.Play("SpinReverse", -1, 0f);
		}
		else
		{
			parent.anim.Play("Spin", -1, 0f);
		}
	}

	private void SetAudioStatus(bool givenStatus)
	{
		if (givenStatus)
		{
			string audioID = "TornadoLoop";
			Transform transform = parent.transform;
			spinAudio = SoundManager.PlayAudioWithDistance(audioID, null, transform, 24f, -1f, 1.2f);
			SoundManager.PlayAudioWithDistance("TornadoStart", parent.transform.position, null, 24f, -1f, 1.2f);
		}
		else if (spinAudio != null && spinAudio.isPlaying)
		{
			spinAudio.Stop();
			spinAudio = null;
			SoundManager.PlayAudioWithDistance("TornadoEnd", parent.transform.position);
		}
	}

	private void CleanUpObjects()
	{
		if (twirlEffect0 != null)
		{
			twirlEffect0.Stop();
		}
		if (twirlEffect1 != null)
		{
			twirlEffect1.Stop();
		}
		if (vortexEffect0 != null)
		{
			vortexEffect0.Stop();
		}
		if (vortexEffect1 != null)
		{
			vortexEffect1.Stop();
		}
		if (vortexEffect2 != null)
		{
			vortexEffect2.Stop();
		}
		parent.movement.moveSpeedStat.RemoveMod(skillID);
		if (currentAtkObj != null)
		{
			UnityEngine.Object.Destroy(currentAtkObj);
		}
		if (curVortex != null && curVortex.gameObject != null)
		{
			UnityEngine.Object.Destroy(curVortex.gameObject);
		}
	}

	private IEnumerator PlayDelayedAirVortex()
	{
		yield return new WaitForSeconds(0.15f);
		if (!onExitCalled)
		{
			vortexEffect1 = PoolManager.GetPoolItem<ParticleEffect>("AirVortex");
			vortexEffect1.reqFollowTrans = true;
			ParticleEffect particleEffect = vortexEffect1;
			float? emissionRate = ((!isUltimate) ? 6 : 3);
			Vector3? position = parent.attackOriginTrans.position;
			Transform attackOriginTrans = parent.attackOriginTrans;
			ParticleSystemOverride vortexOverride = VortexOverride;
			particleEffect.Play(emissionRate, position, vortexOverride, null, attackOriginTrans);
			vortexEffect2 = PoolManager.GetPoolItem<ParticleEffect>("AirVortex");
			vortexEffect2.reqFollowTrans = true;
			ParticleEffect particleEffect2 = vortexEffect2;
			emissionRate = ((!isUltimate) ? 20 : 10);
			position = parent.attackOriginTrans.position;
			attackOriginTrans = parent.attackOriginTrans;
			vortexOverride = VortexOverrideBGWorld;
			particleEffect2.Play(emissionRate, position, vortexOverride, null, attackOriginTrans);
			twirlEffect1 = PoolManager.GetPoolItem<ParticleEffect>("WindTwirlEffect");
			twirlEffect1.reqFollowTrans = true;
			twirlEffect1.Play(isUltimate ? 1 : 2, parent.attackOriginTrans.position, followTransform: parent.attackOriginTrans, localEulerAngles: new Vector3(0f, 0f, -25f), overrides: ParticleEffectOverrides.StartLifeTime0p25);
		}
	}
}

public class UseTornadoKick : SkillState
{
	public new static string staticID = "UseTornadoKick";

	private NumVarStatMod dashSpeedMod;

	private NumVarStatMod dashDurationMod;

	private bool finishedDashing;

	private ChaosQuickStopwatch dashStopwatch = new ChaosQuickStopwatch(0.125f);

	private float dashForceStart;

	private TornadoKickBase currentTK;

	private Attack currentAtk;

	private CircleCollider2D currentAtkCol;

	private Vector2 attackVector;

	private Vector2 currentPosition;

	private ChaosQuickStopwatch kickStopwatch = new ChaosQuickStopwatch(0.15f);

	private ChaosQuickStopwatch postStopwatch = new ChaosQuickStopwatch(0.1f);

	private bool kickStarted;

	private bool tornadoCreated;

	private bool targetHit;

	private string animStr;

	private Vector2 AttackPosition => attackVector + (Vector2)parent.attackOriginTrans.position;

	public UseTornadoKick(FSM parentFSM, Player parentEnt)
		: base(staticID, parentFSM, parentEnt)
	{
		isMovementSkill = true;
		isMeleeSkill = true;
		SetAnimTimes(0.2f, 0.2f, 0.5f, 0.8f, 0.9f);
		dashSpeedMod = new NumVarStatMod(skillID, 0.25f, 10, VarStatModType.Multiplicative);
		dashDurationMod = new NumVarStatMod(skillID, 0.125f, 10, VarStatModType.OverrideWithMods);
	}

	public override void OnEnter()
	{
		BaseOnEnter();
		base.ExecuteSkill();
		inputVector = GetInputVector();
		attackVector = inputVector * 1.75f;
		parent.movement.EndMovement();
		parent.movement.dashSpeedStat.AddMod(dashSpeedMod);
		parent.movement.dashDurationStat.AddMod(dashDurationMod);
		parent.movement.dashTimer = dashDurationMod.modValue;
		parent.movement.dashVector = inputVector;
		parent.TogglePreventFallCollider(status: false);
		parent.ToggleEnemyFloorCollisions(status: false);
		animStr = parent.KickAnimStr;
		kickStopwatch.IsRunning = true;
		kickStarted = false;
		tornadoCreated = false;
		finishedDashing = true;
		targetHit = false;
	}

	public override void Update()
	{
		if (!kickStarted)
		{
			parent.anim.PlayDirectional(animStr, -1, animStartTime);
			if (!tornadoCreated)
			{
				tornadoCreated = true;
				CreateTornado();
			}
			if (!kickStopwatch.IsRunning)
			{
				kickStarted = true;
				finishedDashing = false;
				dashStopwatch.IsRunning = true;
				currentPosition = parent.attackOriginTrans.position;
				PoolManager.GetPoolItem<DashAirBurst>().Burst(currentPosition + inputVector, inputVector, useOffset: false);
				ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("AirWaveShockwave");
				int? particleCount = 1;
				Vector3? position = currentPosition + inputVector * 0.5f;
				Vector3? localEulerAngles = Globals.GetRotationVector(inputVector);
				poolItem.Emit(particleCount, position, null, localEulerAngles);
				PoolManager.GetPoolItem<SectionedTrailEmitter>("WindTrail").Emit(currentPosition, currentPosition + inputVector * 5f);
				CreateDashAttack();
				parent.anim.PlayDirectional(animStr, -1, animExecTime);
			}
		}
		else if (!finishedDashing || postStopwatch.IsRunning)
		{
			if (parent.anim.AnimPlayed(0.6f))
			{
				parent.anim.PlayDirectional(animStr, -1, 0.45f);
			}
		}
		else
		{
			fsm.ChangeState(SlideState.staticID);
		}
	}

	public override void FixedUpdate()
	{
		if (!finishedDashing)
		{
			if (parent.movement.DashToTarget())
			{
				finishedDashing = true;
			}
			if (currentAtk != null)
			{
				currentAtk.rigidbody2D.MovePosition(AttackPosition);
				currentAtk.knockbackMultiplierOverride = Mathf.Lerp(dashForceStart, 20f, dashStopwatch.TimePercentage);
			}
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		parent.TogglePreventFallCollider(status: true);
		parent.ToggleEnemyFloorCollisions();
		parent.movement.dashSpeedStat.RemoveMod(dashSpeedMod);
		parent.movement.dashDurationStat.RemoveMod(dashDurationMod);
		CleanUpObjects();
	}

	private void CleanUpObjects()
	{
		if (currentAtk != null && currentAtk.gameObject != null)
		{
			UnityEngine.Object.Destroy(currentAtk.gameObject);
		}
		if (!targetHit && currentTK != null)
		{
			currentTK.StopTornado();
		}
	}

	private void OnTargetHit(Entity ent)
	{
		if (targetHit || ent == null || ent is Destructible || ent.hurtBoxTransform == null)
		{
			return;
		}
		targetHit = true;
		finishedDashing = true;
		postStopwatch.IsRunning = true;
		parent.movement.EndMovement();
		parent.movement.moveVector = inputVector;
		parent.movement.MoveToMoveVector(20f);
		if (currentAtkCol != null)
		{
			currentAtkCol.radius = 1.75f;
		}
		if (currentAtk != null)
		{
			currentAtk.transform.position = ent.hurtBoxTransform.position;
			if (currentAtk.gameObject != null)
			{
				UnityEngine.Object.Destroy(currentAtk.gameObject, 0.05f);
			}
		}
		if (currentTK != null)
		{
			currentTK.SetHitTarget(ent);
		}
	}

	private void CreateDashAttack()
	{
		currentAtk = ChaosInst<Attack>(Attack.CirclePrefab, AttackPosition);
		currentAtk.SetAttackInfo(parent.skillCategory, skillID, 2);
		currentAtk.knockbackOverwriteVector = inputVector;
		Attack attack = currentAtk;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		currentAtk.gameObject.AddComponent<NegateProjectiles>();
		currentAtkCol = currentAtk.GetComponent<CircleCollider2D>();
		currentAtkCol.radius = 1f;
		dashForceStart = currentAtk.atkInfo.knockbackMultiplier;
		if (currentTK != null)
		{
			currentTK.followTrans = currentAtk.transform;
		}
	}

	private void CreateTornado()
	{
		currentTK = ChaosInst<TornadoKickBase>(TornadoKickBase.Prefab, parent.attackOriginTrans.position);
		currentTK.attack.SetAttackInfo(parent.skillCategory, skillID);
		currentTK.hitCount = ((!IsEmpowered) ? 7 : 10);
	}
}

public class ShootArrowState : ProjectileChainAttackState
{
	public new static string staticID = "ShootArrow";

	private const int UltCount = 20;

	private NumVarStatMod ultMod = new NumVarStatMod("ult", 20f, 10, VarStatModType.Override);

	private Arrow currentAS;

	public override string OnHoldAnimStr => parent.NextHandAnimStr;

	public ShootArrowState(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		hasSignatureVariant = true;
		SetAnimTimes(0.25f, 0.2f, 0.35f);
		shotDelay = 0.08f;
	}

	public override bool IsReady()
	{
		return cooldownRef.chargeCount > 2 && base.IsReady();
	}

	public override void OnEnter()
	{
		base.OnEnter();
		CameraController.ShakeCamera(0.25f);
		if (isUltimate)
		{
			SetChargeCount(givenStatus: true);
			SetSkillLevel(2);
			shotDelay = 0.05f;
		}
		else
		{
			SetSkillLevel(1);
			shotDelay = 0.08f;
		}
	}

	public override void FireChainProjectile()
	{
		GameObject prefab = Arrow.Prefab;
		Quaternion? givenQuaternion = Globals.GetRotationQuaternion(inputVector);
		currentAS = (Arrow)CreateProjectile(prefab, null, givenQuaternion);
		if (IsEmpowered)
		{
			currentAS.disableOnHit = false;
		}
		if (isUltimate)
		{
			currentAS.useHoming = true;
			currentAS.TargetsHitList.AddRange(parent.playerSummonsList);
		}
		FireProjectile(currentAS, inputVector, setKnockbackVector: true, 0f, 0f, string.Empty);
		SoundManager.PlayAudioWithDistance("WindArrowStart", parent.transform.position, null, 24f, -1f, 1.1f);
		PoolManager.GetPoolItem<DashAirBurst>().Burst(parent.attackOriginTrans.position, inputVector);
	}

	public override void OnExit()
	{
		base.OnExit();
		if (isUltimate)
		{
			SetChargeCount(givenStatus: false);
		}
	}

	private void SetChargeCount(bool givenStatus)
	{
		cooldownRef.maxChargeStat.Modify(ultMod, givenStatus);
		cooldownRef.chargeCount = (givenStatus ? 20 : 0);
		StartCooldownTimer(-1f, expendCharge: false);
	}
}

using System;
using System.Collections.Generic;
using UnityEngine;

public class TornadoKickBase : MonoBehaviour
{
	private static GameObject prefab;

	public ParticleSystem impactEmitter;

	public ParticleSystem windEmitterFront;

	public ParticleSystem windEmitterBack;

	[HideInInspector]
	public Rigidbody2D rigidbody2D;

	[HideInInspector]
	public Attack attack;

	[HideInInspector]
	public Transform followTrans;

	private int hitStopwatchID;

	public int hitCount = 10;

	private float hitDelay = 0.125f;

	private bool hitComplete;

	private bool targetHit;

	private Entity followEntity;

	private Entity currentEntity;

	private List<Entity> hitTargetList = new List<Entity>();

	private AttackInfo kbAtkInfo = new AttackInfo();

	private ChaosQuickStopwatch lifeStopwatch = new ChaosQuickStopwatch(5f);

	private ChaosQuickStopwatch audioStopwatch = new ChaosQuickStopwatch(0.625f);

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/TornadoKickBase.prefab"));

	private void Awake()
	{
		rigidbody2D = GetComponent<Rigidbody2D>();
		this.attack = transform.Find("Attack").GetComponent<Attack>();
		Attack attack = this.attack;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		lifeStopwatch.IsRunning = true;
	}

	private void Start()
	{
		SoundManager.PlayAudioWithDistance("TornadoStart", transform.position);
	}

	private void Update()
	{
		if (!lifeStopwatch.IsRunning && gameObject != null)
		{
			UnityEngine.Object.Destroy(gameObject);
		}
	}

	private void FixedUpdate()
	{
		if (hitComplete)
		{
			return;
		}
		if (followTrans != null)
		{
			transform.position = followTrans.position;
		}
		if (targetHit)
		{
			switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
			{
			case StopwatchState.Running:
				attack.collider.enabled = false;
				break;
			case StopwatchState.Ready:
			{
				attack.collider.enabled = true;
				for (int num = hitTargetList.Count - 1; num >= 0; num--)
				{
					currentEntity = hitTargetList[num];
					if (!(currentEntity == null) && !(currentEntity == followEntity))
					{
						kbAtkInfo.knockbackVector = transform.position - currentEntity.transform.position;
						currentEntity.ApplyKnockback(kbAtkInfo);
					}
				}
				hitTargetList.Clear();
				break;
			}
			case StopwatchState.Done:
				hitComplete = true;
				StopTornado();
				break;
			}
		}
		if (!audioStopwatch.IsRunning)
		{
			audioStopwatch.IsRunning = true;
			string audioID = "WindCircle";
			Vector2? soundOrigin = transform.position;
			float overridePitch = UnityEngine.Random.Range(0.75f, 0.9f);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
		}
	}

	private void OnTargetHit(Entity givenEnt)
	{
		hitTargetList.Add(givenEnt);
	}

	public void SetHitTarget(Entity givenEnt)
	{
		if (!targetHit)
		{
			targetHit = true;
			followEntity = givenEnt;
			followTrans = givenEnt.hurtBoxTransform;
			transform.position = followTrans.position;
			impactEmitter.Emit(50);
			hitStopwatchID = ChaosStopwatch.Begin(hitDelay, useInterval: true, hitDelay, hitCount);
		}
	}

	public void StopTornado()
	{
		targetHit = true;
		ChaosStopwatch.Stop(hitStopwatchID);
		windEmitterFront.Stop();
		windEmitterBack.Stop();
		SoundManager.PlayAudioWithDistance("TornadoEnd", transform.position);
		UnityEngine.Object.Destroy(gameObject, 1f);
	}
}
using System;
using Chaos.AnimatorExtensions;
using UnityEngine;

public class Arrow : Projectile
{
	private bool waitingForReset;

	private bool hitWall;

	private bool collided;

	private static GameObject prefab;

	private float elapsedTime;

	private Transform lightTrans;

	private Vector3 lightPos;

	private Light light;

	private bool fullLight;

	private bool startSpeedDecrement;

	private float speedDecrement;

	public bool useHoming;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/Arrow.prefab"));

	public override void Awake()
	{
		base.Awake();
		lightTrans = transform.Find("Light").transform;
		light = lightTrans.GetComponent<Light>();
		fullLight = false;
		startSpeedDecrement = false;
		speedDecrement = 100f;
	}

	public override void Start()
	{
		base.Start();
		if (useHoming)
		{
			Attack attack = attackBox;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			Attack attack2 = attackBox;
			attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		}
	}

	public override void FixedUpdate()
	{
		base.FixedUpdate();
		elapsedTime = Time.fixedDeltaTime;
		if (!fullLight)
		{
			if (light.range < 4f)
			{
				light.range += elapsedTime * 40f;
			}
			else
			{
				fullLight = true;
			}
			return;
		}
		lightPos = lightTrans.position + (Vector3)moveVector * elapsedTime * 8f;
		lightPos.z = lightTrans.position.z - elapsedTime * 5f;
		lightTrans.position = lightPos;
		if (lightTrans.position.z > -1f)
		{
			startSpeedDecrement = true;
		}
		if (startSpeedDecrement && !waitingForReset)
		{
			speedDecrement += elapsedTime * 50f;
			moveSpeed = Mathf.Max(moveSpeed - elapsedTime * speedDecrement, 0f);
		}
		light.intensity -= elapsedTime * 5f;
		light.range -= elapsedTime * 5f;
	}

	public override void HandleCollision(Collider2D other)
	{
		collided = true;
		base.HandleCollision(other);
	}

	public override void HandleWallCollision(Collider2D other)
	{
		hitWall = true;
		collided = true;
		base.HandleWallCollision(other);
	}

	public override void ResetProjectile()
	{
		if (useHoming)
		{
			useHoming = false;
			Attack attack = attackBox;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			nextTargetInfo = Entity.GetClosestTarget(GameController.enemies, transform.position, 8f, playerTagOnly: false, TargetsHitList, parentObject, requireLOS: true, ChaosCollisions.layerUpperWallAndObst);
			TargetsHitList.Clear();
			if (nextTargetInfo != null)
			{
				moveVector = (nextTargetInfo.hurtBoxPosition - transform.position).normalized;
				attackBox.knockbackOverwriteVector = moveVector;
				isPointedAtMoveVector = false;
				fullLight = false;
				light.range = 0f;
				light.intensity = 8f;
				startSpeedDecrement = false;
				moveSpeed = 32f;
				RefreshFlightTime();
				return;
			}
		}
		if (!waitingForReset)
		{
			anim.Play("BreakAlt", -1, 0f);
			if ((!hitWall && !disableOnHit) || (disableOnHit && !collided))
			{
				moveSpeed = UnityEngine.Random.Range(5f, 8f);
				rigidbody2D.velocity = moveVector * moveSpeed;
				anim.speed = UnityEngine.Random.Range(0.75f, 1.5f);
			}
			else
			{
				moveSpeed = 0f;
				rigidbody2D.velocity = Vector3.zero;
				ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("WindWallHitEffect");
				int? particleCount = 1;
				Vector3? position = transform.position;
				Vector3? localEulerAngles = Globals.GetRotationVector(moveVector);
				poolItem.Emit(particleCount, position, null, localEulerAngles);
				anim.speed = UnityEngine.Random.Range(1.25f, 2f);
			}
			waitingForReset = true;
		}
		else if (!waitingForReset || anim.AnimPlayed())
		{
			base.ResetProjectile();
		}
	}

	private void OnTargetHit(Entity givenEntity)
	{
		if (givenEntity != null)
		{
			TargetsHitList.Add(givenEntity.gameObject);
		}
	}
}

